// 判断带头节点的循环单链表是否为空
int IsCirListEmpty(LinkList L) {
    return L->next == L;
}

// 头插法反转单链表，原地逆置
LinkList ReverseList(LinkList L) {
    LNode *p = L->next, *q;
    L->next = NULL;
    while(p != NULL) {
        q = p->next;
        p->next = L->next;
        L->next = p;
        p = q;
    }
    return L;
}

// 头插法创建含n个节点的带头节点单链表
void CreateListHead(LinkList *L, int n) {
    *L = (LNode*)malloc(sizeof(LNode));
    (*L)->next = NULL;
    for(int i=0; i<n; i++) {
        LNode *p = (LNode*)malloc(sizeof(LNode));
        scanf("%d", &p->data);
        p->next = (*L)->next;
        (*L)->next = p;
    }
}

