// 循环队列入队
Status EnQueue(SqQueue *Q, ElemType e) {
    if((Q->rear + 1) % MAXQSIZE == Q->front) return ERROR;
    Q->base[Q->rear] = e;
    Q->rear = (Q->rear + 1) % MAXQSIZE;
    return OK;
}

// 循环队列入队
Status EnQueue(SqQueue *Q, ElemType e) {
    if((Q->rear + 1) % MAXQSIZE == Q->front) return ERROR;
    Q->base[Q->rear] = e;
    Q->rear = (Q->rear + 1) % MAXQSIZE;
    return OK;
}

// 用两个栈实现队列：入队直接压栈1，出队时栈2空则将栈1全部倒入栈2再弹出
void push(int x) { stack1.push(x); }
int pop() {
    if(stack2.empty())
        while(!stack1.empty())
            { stack2.push(stack1.top()); stack1.pop(); }
    int res = stack2.top(); stack2.pop();
    return res;
}

// 链队列出队
Status DeLinkQueue(LinkQueue *Q, ElemType *e) {
    if(Q->front == Q->rear) return ERROR;
    QNode p = Q->front->next;
    e = p->data;
    Q->front->next = p->next;
    if(Q->rear == p) Q->rear = Q->front;
    free(p);
    return OK;
}

// 求nextval数组
void get_nextval(SString T, int nextval[]) {
    int i = 1, j = 0;
    nextval[1] = 0;
    while(i < T[0]) {
        if(j == 0 || T[i] == T[j]) {
            i++; j++;
            if(T[i] != T[j]) nextval[i] = j;
            else nextval[i] = nextval[j];
        } else j = nextval[j];
    }
}

// KMP匹配算法
int Index_KMP(SString S, SString T, int pos) {
    int i = pos, j = 1;
    int next[256]; get_next(T, next);
    while(i <= S[0] && j <= T[0]) {
        if(j == 0 || S[i] == T[j]) { i++; j++; }
        else j = next[j];
    }
    if(j > T[0]) return i - T[0];
    else return 0;
}

// 稀疏矩阵快速转置
Status FastTransposeSMatrix(TSMatrix M, TSMatrix *T) {
    int num[MAXSIZE], cpot[MAXSIZE];
    T->mu = M.nu; T->nu = M.mu; T->tu = M.tu;
    if(T->tu) {
        for(int col=1; col<=M.nu; col++) num[col] = 0;
        for(int t=1; t<=M.tu; t++) num[M.data[t].j]++;
        cpot[1] = 1;
        for(int col=2; col<=M.nu; col++) cpot[col] = cpot[col-1] + num[col-1];
        for(int p=1; p<=M.tu; p++) {
            int col = M.data[p].j;
            int q = cpot[col];
            T->data[q].i = M.data[p].j;
            T->data[q].j = M.data[p].i;
            T->data[q].e = M.data[p].e;
            cpot[col]++;
        }
    }
    return OK;
}

// 稀疏矩阵普通转置
Status TransposeSMatrix(TSMatrix M, TSMatrix *T) {
    T->mu = M.nu; T->nu = M.mu; T->tu = M.tu;
    if(T->tu) {
        int q = 1;
        for(int col = 1; col <= M.nu; col++)
            for(int p = 1; p <= M.tu; p++)
                if(M.data[p].j == col) {
                    T->data[q].i = M.data[p].j;
                    T->data[q].j = M.data[p].i;
                    T->data[q].e = M.data[p].e;
                    q++;
                }
    }
    return OK;
}

// 合并两个升序顺序表，结果存入C并保持升序
void MergeSqList(SqList A, SqList B, SqList *C) {
    int i=0, j=0, k=0;
    while(i<A.length && j<B.length) {
        if(A.data[i] <= B.data[j])
            C->data[k++] = A.data[i++];
        else
            C->data[k++] = B.data[j++];
    }
    while(i < A.length) C->data[k++] = A.data[i++];
    while(j < B.length) C->data[k++] = B.data[j++];
    C->length = k;
}

