// 层序遍历
void LevelOrder(BiTree T) {
    SqQueue Q; InitQueue(&Q);
    BiTree p;
    EnQueue(&Q, T);
    while(!QueueEmpty(Q)) {
        DeQueue(&Q, &p);
        visit(p->data);
        if(p->lchild) EnQueue(&Q, p->lchild);
        if(p->rchild) EnQueue(&Q, p->rchild);
    }
}

// DFS遍历连通图
void DFS(Graph G, int v) {
    visited[v] = TRUE;
    visit(v);
    for(int w = FirstAdjVex(G, v); w >= 0; w = NextAdjVex(G, v, w))
        if(!visited[w]) DFS(G, w);
}

// BFS遍历连通图
void BFS(Graph G, int v) {
    visited[v] = TRUE; visit(v);
    EnQueue(&Q, v);
    while(!QueueEmpty(Q)) {
        DeQueue(&Q, &u);
        for(int w = FirstAdjVex(G, u); w >= 0; w = NextAdjVex(G, u, w))
            if(!visited[w]) { visited[w]=TRUE; visit(w); EnQueue(&Q, w); }
    }
}

// 折半查找实现
int SearchBin(SSTable ST, KeyType key){
    int low=1,high=ST.length;
    while(low<=high){
        int mid=(low+high)/2;
        if(ST.elem[mid].key==key) return mid;
        else if(ST.elem[mid].key>key) high=mid-1;
        else low=mid+1;
    }
    return 0;
}

// 无序顺序表顺序查找
int SearchSeq(SSTable ST, KeyType key){
    int i=ST.length;
    ST.elem[0].key=key;
    while(ST.elem[i].key!=key) i--;
    return i;
}

// 败者树多路归并核心逻辑伪代码
// b[]存放败者段编号，ls[]叶子节点对应k个归并段当前记录
void CreateLoserTree(int ls[],int b[],int k){
    for(int i=0;i<k;i++) b[k+i]=i;
    for(int i=k‑1;i>0;i--) Adjust(ls,b,i);
}
void Adjust(int ls[],int b[],int s){
    int t=(s+k)/2;
    while(t>0){
        if(ls[b[s]]>ls[b[t]]){ int tmp=b[s];b[s]=b[t];b[t]=tmp; s=t; }
        else break;
        t=t/2;
    }
}

// 折半查找实现
int SearchBin(SSTable ST, KeyType key){
    int low=1,high=ST.length;
    while(low<=high){
        int mid=(low+high)/2;
        if(ST.elem[mid].key==key) return mid;
        else if(ST.elem[mid].key>key) high=mid-1;
        else low=mid+1;
    }
    return 0;
}

// 快速排序划分函数
int Partition(SqList &L,int low,int high){
    KeyType pivot=L.r[low].key;
    while(low<high){
        while(low<high && L.r[high].key>=pivot) high--;
        L.r[low]=L.r[high];
        while(low<high && L.r[low].key<=pivot) low++;
        L.r[high]=L.r[low];
    }
    L.r[low].key=pivot;
    return low;
}

// 败者树多路归并核心逻辑伪代码
// b[]存放败者段编号，ls[]叶子节点对应k个归并段当前记录
void CreateLoserTree(int ls[],int b[],int k){
    for(int i=0;i<k;i++) b[k+i]=i;
    for(int i=k‑1;i>0;i--) Adjust(ls,b,i);
}
void Adjust(int ls[],int b[],int s){
    int t=(s+k)/2;
    while(t>0){
        if(ls[b[s]]>ls[b[t]]){ int tmp=b[s];b[s]=b[t];b[t]=tmp; s=t; }
        else break;
        t=t/2;
    }
}

// 败者树多路归并核心逻辑伪代码
// b[]存放败者段编号，ls[]叶子节点对应k个归并段当前记录
void CreateLoserTree(int ls[],int b[],int k){
